def check_lc1(tgraph):
    return tgraph.check_subnet("SW_DMZ", "10.10.10.0/24")


def check_lc2(tgraph):
    return tgraph.check_subnet("SW_OFFICE", "10.10.20.0/24")


def check_lc3(tgraph):
    return tgraph.check_subnet("SW_OT", "10.10.30.0/24")


def check_lc4(tgraph):
    return tgraph.check_subnet("SW_MGMT", "10.10.40.0/24")


def check_lc5(tgraph):
    return tgraph.check_subnet("SW_BRANCH", "10.20.20.0/24")


def check_lc6(tgraph):
    return tgraph.check_subnet("SW_CORE_FW", "10.0.0.0/30")


def check_lc7(tgraph):
    return tgraph.check_subnet("SW_FW_INET", "10.0.0.4/30")


def check_lc8(tgraph):
    return tgraph.check_subnet("SW_CORE_BRANCH", "10.0.0.8/30")


def check_lc9(tgraph):
    return tgraph.check_chain(["WEB", "SW_DMZ", "R_CORE"])


def check_lc10(tgraph):
    return tgraph.check_chain(["PC1", "SW_OFFICE", "R_CORE"])


def check_lc11(tgraph):
    return tgraph.check_chain(["PC2", "SW_OFFICE", "R_CORE"])


def check_lc12(tgraph):
    return tgraph.check_chain(["PLC1", "SW_OT", "R_CORE"])


def check_lc13(tgraph):
    return tgraph.check_chain(["ADMIN", "SW_MGMT", "R_CORE"])


def check_lc14(tgraph):
    return tgraph.check_chain(["R_CORE", "SW_CORE_FW", "FIREWALL"])


def check_lc15(tgraph):
    return tgraph.check_chain(["FIREWALL", "SW_FW_INET", "INTERNET"])


def check_lc16(tgraph):
    return tgraph.check_chain(["R_CORE", "SW_CORE_BRANCH", "R_BRANCH", "SW_BRANCH", "BPC1"])


def check_lc17(tgraph):
    issues = []
    target_nodes = ["R_CORE", "R_BRANCH", "FIREWALL", "INTERNET"]
    for nid in target_nodes:
        ports = tgraph.ports(node_id=nid)
        for port in ports:
            ip = port.get("ip")
            if not ip:
                issues.append({
                    "message": f"Port {port.get('port_id', 'unknown')} on {nid} must have a fixed IPv4 address",
                    "severity": "error",
                    "location": f"{nid}/{port.get('port_id', 'unknown')}",
                    "details": {
                        "issue_kind": "logical.custom.missing_fixed_ip",
                        "repair_target": "graph",
                        "targets": [nid],
                    },
                })
    return issues if issues else []

