{"ok": true, "path": "physical/checkpoints.py", "content": "def check_pc1(tgraph):
    node = tgraph.node("FIREWALL") or {}
    image = node.get("image") or {}
    expected_image_ids = ["opnsense", "pfsense"]
    if image.get("id") not in expected_image_ids:
        return {
            "message": "FIREWALL requires a firewall appliance image.",
            "severity": "error",
            "location": "nodes.FIREWALL.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc1",
                "repair_target": "node.FIREWALL.image",
                "expected_image_ids": expected_image_ids,
                "actual_image_id": image.get("id"),
            },
        }
    return []


def check_pc2(tgraph):
    node = tgraph.node("INTERNET") or {}
    image = node.get("image") or {}
    expected_image_ids = ["linux_internet_gateway"]
    if image.get("id") not in expected_image_ids:
        return {
            "message": "INTERNET requires an internet gateway image.",
            "severity": "error",
            "location": "nodes.INTERNET.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc2",
                "repair_target": "node.INTERNET.image",
                "expected_image_ids": expected_image_ids,
                "actual_image_id": image.get("id"),
            },
        }
    return []
